function [s] = spare_axis()
%SPARE_AXIS  The spare ring's axis: the unit body diagonal, since the three rings are sized alike, so its projection on each axis
%   holds that ring's whole momentum when it carries their root sum square.
%   returns s: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = zeros(3, 1);
    r = (1 / asils.pc.sqrt_(3));
    s = [r; r; r];
end
